import { getActiveOrg, resolveContext } from "../internal/index.js";
import {
  loadProjectLink,
  removeProjectLink,
  saveProjectLink,
} from "../internal/project-link.js";

interface LinkOptions {
  context?: string;
  org?: string;
  cwd?: string;
}

export async function linkCommand(options: LinkOptions = {}): Promise<void> {
  const cwd = options.cwd ?? process.cwd();
  const target = await resolveContext(options.context);
  const org = options.org?.trim() || (await getActiveOrg(target.name)) || "";
  if (!org) {
    console.error(
      chalk.red(
        "\n  No org selected. Run `lobu org set <slug>` or pass `--org <slug>`.\n"
      )
    );
    process.exit(1);
  }

  const link = await saveProjectLink(cwd, { context: target.name, org });
  console.log(chalk.green("\n  Project linked."));
  console.log(chalk.dim(`  Context: ${link.context}`));
  console.log(chalk.dim(`  Org:     ${link.org}`));
  console.log(chalk.dim(`  Path:    ${cwd}/.lobu/project.json\n`));
}

export async function unlinkCommand(
  options: { cwd?: string } = {}
): Promise<void> {
  const cwd = options.cwd ?? process.cwd();
  const existing = await loadProjectLink(cwd);
  if (!existing) {
    console.log(chalk.dim("\n  No project link found.\n"));
    return;
  }
  await removeProjectLink(cwd);
  console.log(chalk.green("\n  Project unlinked.\n"));
}
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

const LINK_DIR = ".lobu";
const LINK_FILE = "project.json";

interface ProjectLink {
  context: string;
  org: string;
  /** ISO timestamp the link was written. */
  linkedAt: string;
}

function linkPath(cwd: string): string {
  return join(cwd, LINK_DIR, LINK_FILE);
}

export async function loadProjectLink(
  cwd: string
): Promise<ProjectLink | null> {
  try {
    const raw = await readFile(linkPath(cwd), "utf-8");
    const parsed = JSON.parse(raw) as Partial<ProjectLink>;
    if (
      typeof parsed.context !== "string" ||
      typeof parsed.org !== "string" ||
      typeof parsed.linkedAt !== "string"
    ) {
      return null;
    }
    return {
      context: parsed.context,
      org: parsed.org,
      linkedAt: parsed.linkedAt,
    };
  } catch {
    return null;
  }
}

export async function saveProjectLink(
  cwd: string,
  link: Omit<ProjectLink, "linkedAt">
): Promise<ProjectLink> {
  await mkdir(join(cwd, LINK_DIR), { recursive: true });
  const full: ProjectLink = { ...link, linkedAt: new Date().toISOString() };
  await writeFile(linkPath(cwd), `${JSON.stringify(full, null, 2)}\n`);

  // Keep the link file out of version control by default.
  const gitignorePath = join(cwd, ".gitignore");
  try {
    const existing = await readFile(gitignorePath, "utf-8");
    if (!/^\.lobu\/?$/m.test(existing)) {
      const sep = existing.endsWith("\n") ? "" : "\n";
      await writeFile(gitignorePath, `${existing}${sep}.lobu/\n`);
    }
  } catch {
    // No .gitignore — init writes one during scaffolding.
  }

  return full;
}

