export interface ChannelKeyRow {
  platform: string;
  /** As stored on the binding — may be platform-prefixed (`slack:C…`) or bare. */
  channel_id: string;
  /** Workspace/tenant id (Slack `T…`); required to form the key. */
  team_id: string | null;
}

/**
