              AND mei.namespace = 'auth_user_id'
              AND mei.identifier = ${userParam}
              AND mei.source_connector = 'auth:signup'
              AND mei.deleted_at IS NULL
            LIMIT 1
          )
      ))
    )`;
  return { sql, params: [scope.organizationId, scope.principal] };
}
