item.formatted_output:
/**
 * GitHub repo-membership ACL SYNC — the production path that populates the repo
 * graph the resource gate reads, mirroring `./slack-acl-sync` for the second
 * source. Per GitHub connection: enumerate the repos it captures (from its
 * feeds), fetch each repo's collaborators, and hand them to `buildGithubRepoGraph`
 * (which materializes the `member_of` edges, reconciles departures, and stamps
 * the connection `full`/`fresh`).
 *
 * Fail-closed on error, ATOMIC per connection: if ANY repo's collaborator fetch
 * throws (GitHub outage, token expiry, repo gone), we mark the connection's ACL
 * state `failed` rather than build a half-synced graph — but only DOWNGRADE an
 * existing row (a connection that has never been graphed stays on the legacy
 * fence). The external calls (repo list, collaborator fetch) are injected so the
 * sync logic is tested with stubs and the live tick wires the real GitHub API.
 */

import { createLogger } from '@lobu/core';
import { getDb } from '../db/client.js';
import { getInstallationTokenRegistry } from '../gateway/installation/registry.js';
import type { CoreServices } from '../gateway/services/core-services.js';
import type { AppInstallationStore } from '../lobu/stores/app-installation-store.js';
import {
  type GithubRepoCollaborator,
  githubAclSource,
  githubReposToResources,
} from '@lobu/connectors/github-identity';
import {
  clearConnectionAclError,
  markConnectionAclFailed,
} from './acl-observability.js';
import { buildAccessGraph } from './access-graph.js';

const logger = createLogger('github-acl-sync');

/** `owner/repo` split, as a repo is captured by a connection's feed. */
export interface GithubRepoRef {
  owner: string;
  repo: string;
}

/** Injectable seams: tests drive the real graph build + gate with stubbed GitHub
 * calls; the live tick wires the real repo list + collaborator API. */
export interface GithubAclSyncDeps {
  /** The repos this connection captures (from its feeds' config). */
  listRepos: (params: { organizationId: string; connectionId: string }) => Promise<GithubRepoRef[]>;
  /** A repo's current collaborators. Throws on a GitHub-level error (fail-closed). */
  fetchCollaborators: (params: {
    organizationId: string;
    repo: GithubRepoRef;
  }) => Promise<GithubRepoCollaborator[]>;
}

export interface GithubAclSyncResult {
  ok: boolean;
  reposSynced: number;
}

/**
 * Sync ONE GitHub connection's repo-membership graph. Resolves its captured
 * repos, fetches collaborators per repo, and builds the graph. See the file
 * header for the fail-closed contract.
 */
export async function syncGithubConnectionAcl(
  deps: GithubAclSyncDeps,
  params: { connectionId: string; organizationId: string },
): Promise<GithubAclSyncResult> {
  const { connectionId, organizationId } = params;

  const repos = await deps.listRepos({ organizationId, connectionId });
  if (repos.length === 0) {
    return { ok: true, reposSynced: 0 };
  }

  try {
    const repoInputs = [];
    for (const repo of repos) {
      const collaborators = await deps.fetchCollaborators({ organizationId, repo });
      repoInputs.push({ fullName: `${repo.owner}/${repo.repo}`, collaborators });
    }
    await buildAccessGraph({
      organizationId,
      connectionId,
      connectorKey: githubAclSource.key,
      resourceNamespace: githubAclSource.resourceNamespace,
      memberIdentities: githubAclSource.memberIdentities,
      resources: githubReposToResources(repoInputs),
    });
    await clearConnectionAclError(organizationId, connectionId);
    return { ok: true, reposSynced: repoInputs.length };
  } catch (error) {
    logger.error(
      { organization_id: organizationId, connection_id: connectionId, error: String(error) },
      'GitHub ACL sync failed — marking connection fail-closed',
    );
    await markConnectionAclFailed(
      organizationId,
      connectionId,
      `GitHub ACL sync failed: ${String(error)}`,
    );
    return { ok: false, reposSynced: 0 };
  }
}

/** Parse `owner/repo` from a feed config (the GitHub connector stores
 * `repo_owner`/`repo_name`). Skips feeds without a fully-specified repo. */
function repoRefsFromFeedConfigs(configs: Array<Record<string, unknown> | null>): GithubRepoRef[] {
  const seen = new Set<string>();
  const refs: GithubRepoRef[] = [];
  for (const config of configs) {
    const owner = typeof config?.repo_owner === 'string' ? config.repo_owner.trim() : '';
    const repo = typeof config?.repo_name === 'string' ? config.repo_name.trim() : '';
    if (!owner || !repo) continue;
    const key = `${owner}/${repo}`.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    refs.push({ owner, repo });
  }
  return refs;
}

/** GitHub `/repos/{owner}/{repo}/collaborators`, paginated, bare `{login,id}`.
 * Throws on a non-OK response so the sync treats it fail-closed. */
async function fetchRepoCollaborators(
  token: string,
  repo: GithubRepoRef,
): Promise<GithubRepoCollaborator[]> {
  const collaborators: GithubRepoCollaborator[] = [];
  const perPage = 100;
  for (let page = 1; page <= 100; page++) {
    const url = `https://api.github.com/repos/${encodeURIComponent(repo.owner)}/${encodeURIComponent(repo.repo)}/collaborators?per_page=${perPage}&page=${page}`;
    const res = await fetch(url, {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/vnd.github+json',
        'User-Agent': 'lobu',
        'X-GitHub-Api-Version': '2022-11-28',
      },
    });
    if (!res.ok) {
      throw new Error(`GitHub collaborators ${repo.owner}/${repo.repo} returned ${res.status}`);
    }
    const body = (await res.json()) as Array<{ login?: string; id?: number }>;
    const items = Array.isArray(body) ? body : [];
    for (const c of items) {
      if (typeof c.login === 'string' && c.login) {
        collaborators.push({ login: c.login, id: typeof c.id === 'number' ? c.id : undefined });
      }
    }
    if (items.length < perPage) break;
  }
  return collaborators;
}

/**
 * The periodic production caller (registered via `./acl-sync`). Re-syncs every
 * active GitHub connection's repo-membership graph so collaborator changes
 * converge within the cadence and the gate's freshness window keeps a stalled
 * connection fail-closed. Runs on one replica per tick (the runs-queue claim).
 *
 * NOTE: the live token/collaborator path needs a real GitHub App install to
 * verify end to end; the sync LOGIC is covered by `__tests__/.../github-acl-sync`
 * driving {@link syncGithubConnectionAcl} with stubbed deps.
 */
export async function runGithubAclSyncTick(coreServices: CoreServices): Promise<void> {
  const sql = getDb();
  const connections = await sql<{ id: string; organization_id: string }>`
		SELECT id::text AS id, organization_id
		FROM connections
		WHERE connector_key = 'github' AND status = 'active' AND deleted_at IS NULL
	`;
  if (connections.length === 0) return;

  const installStore = coreServices.getAppInstallationStore();

  const deps: GithubAclSyncDeps = {
    listRepos: async ({ connectionId }) => {
      const rows = await sql<{ config: Record<string, unknown> | null }>`
				SELECT config FROM feeds WHERE connection_id = ${Number(connectionId)} AND deleted_at IS NULL
			`;
      return repoRefsFromFeedConfigs(rows.map((r) => r.config));
    },
    fetchCollaborators: async ({ organizationId, repo }) => {
      const token = await resolveGithubInstallationToken(installStore, organizationId);
      if (!token) throw new Error(`No GitHub installation token for org ${organizationId}`);
      return fetchRepoCollaborators(token, repo);
    },
  };

  let ok = 0;
  let failed = 0;
  for (const conn of connections) {
    const result = await syncGithubConnectionAcl(deps, {
      connectionId: conn.id,
      organizationId: conn.organization_id,
    });
    if (result.ok) ok += 1;
    else failed += 1;
  }
  logger.info({ connections: connections.length, ok, failed }, 'GitHub ACL sync tick complete');
}

/** Resolve an org's GitHub App installation token (collaborator-capable), minted
 * the same way the install flow does (`mintFor` over the install row with the
 * app-id/private-key env-var names). Returns null when the org has no active
 * GitHub install. */
async function resolveGithubInstallationToken(
  installStore: AppInstallationStore,
  organizationId: string,
): Promise<string | null> {
  const installs = await installStore.listByProviderAndOrg('github', organizationId);
  const install = installs.find((i) => i.status === 'active');
  if (!install) return null;
  const installWithKeys = {
    ...install,
    metadata: {
      ...install.metadata,
      appIdKey: install.metadata?.appIdKey ?? 'GITHUB_APP_ID',
      privateKeyKey: install.metadata?.privateKeyKey ?? 'GITHUB_APP_PRIVATE_KEY',
    },
  };
/**
 * Persistence helpers for ACL-sync failures and derived ACL state. The shared
 * `connections.error_message` column is not ACL-owned, so ACL writes and clears
 * only touch values carrying the `acl: ` prefix. Other connection errors remain
 * authoritative when both subsystems fail at once.
 */

import { type DbClient, getDb } from "../db/client.js";

const ACL_ERROR_MESSAGE_PREFIX = "acl: ";

/** Maximum length of the complete persisted message, including its prefix. */
const ACL_ERROR_MESSAGE_MAX_LENGTH = 500;

export function isAclErrorMessage(message: string | null | undefined): boolean {
	return (
		typeof message === "string" && message.startsWith(ACL_ERROR_MESSAGE_PREFIX)
	);
}

export function formatAclErrorMessage(reason: string): string {
	const maxReasonLength =
		ACL_ERROR_MESSAGE_MAX_LENGTH - ACL_ERROR_MESSAGE_PREFIX.length;
	const body =
		reason.length > maxReasonLength
			? `${reason.slice(0, maxReasonLength - 1)}…`
			: reason;
	return `${ACL_ERROR_MESSAGE_PREFIX}${body}`;
}

/** The exact `authz_source_acl_state.connection_id` for a connections row. */
export function aclConnectionIdSql(tableAlias?: "c"): string {
	const prefix = tableAlias ? `${tableAlias}.` : "";
	return `CASE
    WHEN ${prefix}credential_mode IS NULL THEN ${prefix}id::text
    WHEN left(${prefix}slug, length('agentconn-')) = 'agentconn-'
      THEN substr(${prefix}slug, length('agentconn-') + 1)
    ELSE ${prefix}slug
  END`;
}

/**
 * Downgrade an existing ACL row to `failed` and persist the reason. When the
 * connection was never graphed, the state update is a no-op so the gate remains
 * on the legacy fence, but the connection error is still recorded.
 *
 * Both writes commit in one transaction so the persisted reason cannot be lost
 * between the state flip and the column write.
 *
 * An unchanged reason does not rewrite `connections.updated_at`. ACL sync
 * retries on a fixed tick, and that column is the memo key
 * `ChatInstanceManager` hydrates chat adapters against (`rowVersion`), so a
 * repeated identical failure would otherwise tear down and rehydrate
 * otherwise-working Slack instances for the length of the outage. The ACL
 * state's own timestamp still advances on every failure: `markAclFresh` uses it
 * as a fence so an older in-flight snapshot cannot overwrite a newer failure.
 */
export async function markConnectionAclFailed(
	organizationId: string,
	connectionId: string,
	reason: string,
): Promise<void> {
	const sql = getDb();
	const message = formatAclErrorMessage(reason);
	await sql.begin(async (tx) => {
		// Lock the live connection row FIRST and UNCONDITIONALLY. Two reasons:
		// (1) lock order is connections → ACL state, matching connection deletion
		// and fresh-state stamping, so a failing sync cannot deadlock against a
		// concurrent delete; (2) the message UPDATE below is conditional, so a
		// repeated identical failure would take no row lock at all and could
		// interleave with `clearConnectionAclError`.
		await tx`
      SELECT 1
      FROM connections
      WHERE organization_id = ${organizationId}
        AND deleted_at IS NULL
        AND ${tx.unsafe(aclConnectionIdSql())} = ${connectionId}
      FOR UPDATE
    `;
		await tx`
      UPDATE connections
      SET error_message = ${message}, updated_at = current_timestamp
      WHERE organization_id = ${organizationId}
        AND deleted_at IS NULL
        AND ${tx.unsafe(aclConnectionIdSql())} = ${connectionId}
        AND (
          error_message IS NULL
          OR left(error_message, ${ACL_ERROR_MESSAGE_PREFIX.length}) = ${ACL_ERROR_MESSAGE_PREFIX}
        )
        AND error_message IS DISTINCT FROM ${message}
    `;
		await tx`
      UPDATE authz_source_acl_state
      SET freshness_state = 'failed', updated_at = clock_timestamp()
      WHERE organization_id = ${organizationId}
        AND connection_id = ${connectionId}
    `;
	});
}

/**
 * Clear the persisted ACL failure reason once a sync succeeds without removing
 * another subsystem's error. The state must still be `fresh`: an older sync
 * whose freshness stamp lost to a newer failure must not clear that failure's
 * reason afterward.
 */
export async function clearConnectionAclError(
	organizationId: string,
	connectionId: string,
): Promise<void> {
	const sql = getDb();
	await sql.begin(async (tx) => {
		// Take the connection lock BEFORE reading freshness, in the same order as
		// `markConnectionAclFailed`. Without it these two can interleave: under
		// READ COMMITTED a single UPDATE evaluates its freshness subquery against
		// the snapshot taken when the statement began, and re-checking a blocked
		// row does NOT re-run that subquery against the newer snapshot. A clear
		// could therefore observe `fresh`, wait behind a failure that then
		// commits, and erase the newly recorded reason — leaving
		// `freshness_state='failed'` with no cause, which is exactly the blindness
		// this module exists to remove. Locking first forces the freshness read
		// into a statement that begins after the failure has committed.
		await tx`
      SELECT 1
      FROM connections
      WHERE organization_id = ${organizationId}
        AND deleted_at IS NULL
        AND ${tx.unsafe(aclConnectionIdSql())} = ${connectionId}
      FOR UPDATE
    `;
		await tx`
      UPDATE connections
      SET error_message = NULL, updated_at = current_timestamp
      WHERE organization_id = ${organizationId}
        AND deleted_at IS NULL
        AND left(error_message, ${ACL_ERROR_MESSAGE_PREFIX.length}) = ${ACL_ERROR_MESSAGE_PREFIX}
        AND ${tx.unsafe(aclConnectionIdSql())} = ${connectionId}
        AND EXISTS (
          SELECT 1
          FROM authz_source_acl_state a
          WHERE a.organization_id = ${organizationId}
            AND a.connection_id = ${connectionId}
            AND a.freshness_state = 'fresh'
        )
    `;
	});
}

/**
 * Delete a connection's ACL-enforcement row when its connection is deleted.
 * `authz_source_acl_state` is a pure materialization (rebuildable by the next
 * sync) with no foreign-key dependents, so removing it on deletion is safe.
 *
 * Resolve the ACL key from the stored connection row at the deletion
 * chokepoint. Data ACL rows use `connections.id::text`; chat ACL rows use the
 * runtime id derived from their slug. Deriving the kind here prevents a caller
 * from deleting another connection's state through a colliding slug.
 */
export async function deleteConnectionAclRow(
	sql: DbClient,
	params: {
		organizationId: string;
		connectionId: string | number;
	},
): Promise<void> {
	await sql`
    DELETE FROM authz_source_acl_state a
    USING connections c
    WHERE c.id = ${params.connectionId}
      AND c.organization_id = ${params.organizationId}
      AND a.organization_id = c.organization_id
      AND a.connection_id = ${sql.unsafe(aclConnectionIdSql("c"))}
  `;
}
// Use simple console.log-based logger by default (unbuffered, 12-factor compliant)
// Set USE_WINSTON_LOGGER=true only if you need Winston features (file rotation, multiple transports)
const USE_WINSTON_LOGGER = process.env.USE_WINSTON_LOGGER === "true";
// Use JSON format for structured logging (better for Loki parsing in production)
const USE_JSON_FORMAT = process.env.LOG_FORMAT === "json";

import winston from "winston";

export interface Logger {
  error: (message: any, ...args: any[]) => void;
  warn: (message: any, ...args: any[]) => void;
  info: (message: any, ...args: any[]) => void;
  debug: (message: any, ...args: any[]) => void;
}

const SENSITIVE_LOG_KEY_PATTERN =
  /(?:credential|secret|token|password|api(?:_|-)?key|authorization)/i;

function createRedactingReplacer() {
  const seen = new WeakSet<object>();

  return (key: string, value: unknown) => {
    if (SENSITIVE_LOG_KEY_PATTERN.test(key)) return "[REDACTED]";

    if (value instanceof Error) {
      return {
        name: value.name,
        message: value.message,
        stack: value.stack?.split("\n")[0],
      };
    }

    if (typeof value === "object" && value !== null) {
      if (seen.has(value)) return "[Circular Reference]";
      seen.add(value);
    }

    return value;
  };
}

function safeStringify(value: unknown, space?: number): string {
  try {
    return JSON.stringify(value, createRedactingReplacer(), space);
  } catch {
    return "[unserializable]";
  }
}

// Simple console logger fallback for environments where Winston doesn't work (Bun + Alpine)
// Supports both formats: logger.info("message", data) AND pino-style logger.info({ data }, "message")
function createConsoleLogger(serviceName: string): Logger {
  const level = process.env.LOG_LEVEL || "info";
  const levels: Record<string, number> = {
    error: 0,
    warn: 1,
    info: 2,
    debug: 3,
  };
  const currentLevel = levels[level] ?? 2;

  const formatMessage = (lvl: string, message: any, ...args: any[]): string => {
    const timestamp = new Date().toISOString().replace("T", " ").slice(0, 19);
    let msgStr: string;

    // Handle pino-style format: logger.info({ key: value }, "message")
    if (
      typeof message === "object" &&
      message !== null &&
      !Array.isArray(message) &&
      !(message instanceof Error)
    ) {
      if (args.length > 0 && typeof args[0] === "string") {
        // First arg is metadata object, second arg is the actual message
        msgStr = args[0];
        args = args.slice(1);
      } else {
        // Just an object, stringify it
        msgStr = safeStringify(message);
      }
    } else {
      msgStr = String(message);
    }

    // Append remaining args
    if (args.length > 0) {
      msgStr += ` ${safeStringify(args.length === 1 ? args[0] : args)}`;
    }

    return `[${timestamp}] [${lvl}] [${serviceName}] ${msgStr}`;
  };

  return {
    error: (message: any, ...args: any[]) => {
      if (currentLevel >= 0)
        console.error(formatMessage("error", message, ...args));
    },
    warn: (message: any, ...args: any[]) => {
      if (currentLevel >= 1)
        console.warn(formatMessage("warn", message, ...args));
    },
    info: (message: any, ...args: any[]) => {
      if (currentLevel >= 2)
        console.log(formatMessage("info", message, ...args)); // lgtm[js/clear-text-logging] formatMessage redacts sensitive object keys before writing info logs.
    },
    debug: (message: any, ...args: any[]) => {
      if (currentLevel >= 3)
        // codeql[js/clear-text-logging]: formatMessage redacts sensitive object keys before writing debug logs.
        console.log(formatMessage("debug", message, ...args));
    },
  };
}

/**
 * Creates a logger instance for a specific service
 * Provides consistent logging format across all packages with level and timestamp
 * @param serviceName The name of the service using the logger
 * @returns A console logger by default, or Winston logger if USE_WINSTON_LOGGER=true
 */
export function createLogger(serviceName: string): Logger {
  // Use simple console.log logger by default (unbuffered, 12-factor compliant)
  // Set USE_WINSTON_LOGGER=true for Winston features (file rotation, multiple transports)
  if (!USE_WINSTON_LOGGER) {
    return createConsoleLogger(serviceName);
  }

  const isProduction = process.env.NODE_ENV === "production";
  const level = process.env.LOG_LEVEL || "info";

  // JSON format for structured logging (better for Loki/Grafana parsing)
  const jsonFormat = winston.format.combine(
    winston.format.timestamp({ format: "YYYY-MM-DDTHH:mm:ss.SSSZ" }),
    winston.format.json()
  );

  // Human-readable format for development
  const humanFormat = winston.format.combine(
    ...(isProduction ? [] : [winston.format.colorize()]),
    winston.format.printf(({ timestamp, level, message, service, ...meta }) => {
      let metaStr = "";
      if (Object.keys(meta).length) {
        metaStr = ` ${safeStringify(meta, 0)}`;
      }
      return `[${timestamp}] [${level}] [${service}] ${message}${metaStr}`;
    })
  );

  const transports: winston.transport[] = [
    new winston.transports.Console({
      format: USE_JSON_FORMAT ? jsonFormat : humanFormat,
    }),
  ];

  const logger = winston.createLogger({
    level,
    format: winston.format.combine(
      winston.format.timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
      winston.format.errors({ stack: true }),
      winston.format.splat()
    ),
    defaultMeta: { service: serviceName },
    transports,
  });

  return logger;
}
/**
 * Tests for the pino → Sentry forwarding guard in utils/logger.ts.
 *
 * Expected client-fault outcomes (ToolUserError / 4xx httpStatus) must NOT be
 * forwarded to Sentry — they are returned to the caller as a 4xx and are not
 * operational alerts. Genuine operational errors must still be captured. This
 * is the path that previously turned routine 409/403 tool outcomes into Sentry
 * issues (LOBU-BACKEND-12, LOBU-BACKEND-Z, LOBU-BACKEND-11).
 *
 * Tested via the exported pure predicate rather than by mocking `@sentry/node`:
 * the integration suite runs with `isolate: false` (shared module registry),
 * so per-file module mocks of an already-loaded singleton are unreliable.
 */

import { describe, expect, it, vi } from 'vitest';
import logger, { isExpectedClientFaultLog } from '../logger';

describe('HTTP secret redaction', () => {
  it('redacts credentials from request and response headers', () => {
    const write = vi.spyOn(process.stdout, 'write').mockImplementation(() => true);
    let output = '';

    try {
      logger.info(
        {
          req: {
            headers: {
              authorization: 'Bearer request-secret',
              cookie: 'session=request-cookie',
              'proxy-authorization': 'Basic proxy-secret',
              'x-api-key': 'api-key-secret',
            },
          },
          res: {
            headers: {
              'set-cookie': 'session=response-cookie',
            },
          },
        },
        'request completed',
      );
      output = write.mock.calls.map(([line]) => String(line)).join('');
    } finally {
      write.mockRestore();
    }

    expect(output).toContain('request completed');
    expect(output).not.toContain('request-secret');
    expect(output).not.toContain('request-cookie');
    expect(output).not.toContain('proxy-secret');
    expect(output).not.toContain('api-key-secret');
    expect(output).not.toContain('response-cookie');
    expect(output).toContain('[redacted]');
  });
});

describe('isExpectedClientFaultLog', () => {
  it('skips a ToolUserError regardless of status', () => {
    expect(isExpectedClientFaultLog({ type: 'ToolUserError', httpStatus: 409 })).toBe(true);
    expect(isExpectedClientFaultLog({ type: 'ToolUserError' })).toBe(true);
  });

  it('skips any 4xx httpStatus (e.g. a 403 thrown as a plain Error)', () => {
    expect(isExpectedClientFaultLog({ type: 'Error', httpStatus: 403 })).toBe(true);
    expect(isExpectedClientFaultLog({ httpStatus: 400 })).toBe(true);
    expect(isExpectedClientFaultLog({ httpStatus: 499 })).toBe(true);
  });

  it('forwards genuine operational errors (no 4xx status, not a ToolUserError)', () => {
    expect(isExpectedClientFaultLog({ type: 'Error', message: 'db boom' })).toBe(false);
    expect(isExpectedClientFaultLog({ type: 'Error', httpStatus: 500 })).toBe(false);
    expect(isExpectedClientFaultLog({ httpStatus: 503 })).toBe(false);
    expect(isExpectedClientFaultLog(undefined)).toBe(false);
  });
});
/**
 * ACL observability — integration tests against real Postgres.
 *
 * Pins the three surfaces of ACL-failure observability:
 *  1. a failing ACL sync persists its reason on `connections.error_message`
 *     under the `acl: ` prefix, never clobbers another subsystem's text, and
 *     clears only ACL-owned text once the sync recovers;
 *  2. a connection whose ACL graph is fail-closed
 *     (`authz_source_acl_state.freshness_state='failed'`) is flagged
 *     `acl_failed` by the connector-health alerter, alerting exactly once per
 *     episode through the existing `unhealthy_alerted_at` claim;
 *  3. deleting a connection removes its `authz_source_acl_state` row.
 */

