// Use simple console.log-based logger by default (unbuffered, 12-factor compliant)
// Set USE_WINSTON_LOGGER=true only if you need Winston features (file rotation, multiple transports)
const USE_WINSTON_LOGGER = process.env.USE_WINSTON_LOGGER === "true";
// Use JSON format for structured logging (better for Loki parsing in production)
const USE_JSON_FORMAT = process.env.LOG_FORMAT === "json";

import winston from "winston";

export interface Logger {
  error: (message: any, ...args: any[]) => void;
  warn: (message: any, ...args: any[]) => void;
  info: (message: any, ...args: any[]) => void;
  debug: (message: any, ...args: any[]) => void;
}

const SENSITIVE_LOG_KEY_PATTERN =
  /(?:credential|secret|token|password|api(?:_|-)?key|authorization)/i;

function createRedactingReplacer() {
  const seen = new WeakSet<object>();

  return (key: string, value: unknown) => {
    if (SENSITIVE_LOG_KEY_PATTERN.test(key)) return "[REDACTED]";

    if (value instanceof Error) {
      return {
        name: value.name,
        message: value.message,
        stack: value.stack?.split("\n")[0],
      };
    }

    if (typeof value === "object" && value !== null) {
      if (seen.has(value)) return "[Circular Reference]";
      seen.add(value);
    }

    return value;
  };
}

function safeStringify(value: unknown, space?: number): string {
  try {
    return JSON.stringify(value, createRedactingReplacer(), space);
  } catch {
    return "[unserializable]";
  }
}

// Simple console logger fallback for environments where Winston doesn't work (Bun + Alpine)
// Supports both formats: logger.info("message", data) AND pino-style logger.info({ data }, "message")
function createConsoleLogger(serviceName: string): Logger {
  const level = process.env.LOG_LEVEL || "info";
  const levels: Record<string, number> = {
    error: 0,
    warn: 1,
    info: 2,
    debug: 3,
  };
  const currentLevel = levels[level] ?? 2;

  const formatMessage = (lvl: string, message: any, ...args: any[]): string => {
    const timestamp = new Date().toISOString().replace("T", " ").slice(0, 19);
    let msgStr: string;

    // Handle pino-style format: logger.info({ key: value }, "message")
    if (
      typeof message === "object" &&
      message !== null &&
      !Array.isArray(message) &&
      !(message instanceof Error)
    ) {
      if (args.length > 0 && typeof args[0] === "string") {
        // First arg is metadata object, second arg is the actual message
        msgStr = args[0];
        args = args.slice(1);
      } else {
        // Just an object, stringify it
        msgStr = safeStringify(message);
      }
    } else {
      msgStr = String(message);
    }

    // Append remaining args
    if (args.length > 0) {
      msgStr += ` ${safeStringify(args.length === 1 ? args[0] : args)}`;
    }

    return `[${timestamp}] [${lvl}] [${serviceName}] ${msgStr}`;
  };

  return {
    error: (message: any, ...args: any[]) => {
      if (currentLevel >= 0)
        console.error(formatMessage("error", message, ...args));
    },
    warn: (message: any, ...args: any[]) => {
      if (currentLevel >= 1)
        console.warn(formatMessage("warn", message, ...args));
    },
    info: (message: any, ...args: any[]) => {
      if (currentLevel >= 2)
        console.log(formatMessage("info", message, ...args)); // lgtm[js/clear-text-logging] formatMessage redacts sensitive object keys before writing info logs.
    },
    debug: (message: any, ...args: any[]) => {
      if (currentLevel >= 3)
        // codeql[js/clear-text-logging]: formatMessage redacts sensitive object keys before writing debug logs.
        console.log(formatMessage("debug", message, ...args));
    },
  };
}

/**
 * Creates a logger instance for a specific service
 * Provides consistent logging format across all packages with level and timestamp
 * @param serviceName The name of the service using the logger
 * @returns A console logger by default, or Winston logger if USE_WINSTON_LOGGER=true
 */
export function createLogger(serviceName: string): Logger {
  // Use simple console.log logger by default (unbuffered, 12-factor compliant)
  // Set USE_WINSTON_LOGGER=true for Winston features (file rotation, multiple transports)
  if (!USE_WINSTON_LOGGER) {
    return createConsoleLogger(serviceName);
  }

  const isProduction = process.env.NODE_ENV === "production";
  const level = process.env.LOG_LEVEL || "info";

  // JSON format for structured logging (better for Loki/Grafana parsing)
  const jsonFormat = winston.format.combine(
    winston.format.timestamp({ format: "YYYY-MM-DDTHH:mm:ss.SSSZ" }),
    winston.format.json()
  );

  // Human-readable format for development
  const humanFormat = winston.format.combine(
    ...(isProduction ? [] : [winston.format.colorize()]),
    winston.format.printf(({ timestamp, level, message, service, ...meta }) => {
      let metaStr = "";
      if (Object.keys(meta).length) {
        metaStr = ` ${safeStringify(meta, 0)}`;
      }
      return `[${timestamp}] [${level}] [${service}] ${message}${metaStr}`;
    })
  );

  const transports: winston.transport[] = [
    new winston.transports.Console({
      format: USE_JSON_FORMAT ? jsonFormat : humanFormat,
    }),
  ];

  const logger = winston.createLogger({
    level,
    format: winston.format.combine(
      winston.format.timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
      winston.format.errors({ stack: true }),
      winston.format.splat()
    ),
    defaultMeta: { service: serviceName },
    transports,
  });

  return logger;
}
import * as Sentry from '@sentry/node';
import pino from 'pino';

/**
 * Logger utility using Pino for structured logging
 *
 * Log Levels:
 * - trace (10): Very detailed debugging
 * - debug (20): Debugging information
 * - info (30): Informational messages (default in production)
 * - warn (40): Warning messages
 * - error (50): Error messages
 * - fatal (60): Fatal errors
 */

// Determine log level from environment.
// Reads process.env.ENVIRONMENT (set to "production" by the Helm chart). The
// previous `(globalThis as any).ENVIRONMENT` was never assigned anywhere, so
// production silently logged at debug level (verbose + costly).
const getLogLevel = (): pino.Level => {
  const env = process.env.ENVIRONMENT || process.env.NODE_ENV || 'development';

  if (env === 'production') {
    return 'info';
  }
  return 'debug';
};

// pino's default error serializer only fires for the `err` key, so
// `logger.error({ error }, '...')` silently logs `error: {}` (Error's own
// fields are non-enumerable). Register the same serializer on the `error`
// key too so either spelling produces a real stack/message. Found during
// the 2026-05-16 prod outage where every queue failure logged `error: {}`
// and hid `column "events.search_tsv" does not exist`.
const errSerializer = pino.stdSerializers.err;

const HTTP_SECRET_HEADER_PATHS = [
  'req.headers.authorization',
  'req.headers.cookie',
  'req.headers["proxy-authorization"]',
  'req.headers["x-api-key"]',
  'res.headers["set-cookie"]',
] as const;

/**
 * Sentry forwarding for logger.error() and logger.fatal().
 *
 * Prior to this hook, `logger.error(...)` only wrote to stdout. The Sentry
 * capture middleware in server.ts:85-113 only fires on HTTP 500 responses,
 * so error-logged failures inside background jobs (CheckDueFeeds, runs
 * queue, scheduled tasks) were invisible to monitoring. The 2026-05-16
 * audit found ~1914 errors / 5 min in stdout with zero Sentry issues.
 *
 * In-process dedupe: repeating errors are common (e.g. an orphan feed
 * fails every 1-min CheckDueFeeds tick). We fingerprint by
 * (msg, err.type, top stack frame) and only forward once per
 * SENTRY_DEDUPE_WINDOW_MS per fingerprint. Sentry has its own grouping
 * but every captureException still incurs an HTTP call + cost; this
 * cuts the load without losing signal.
 */
const SENTRY_DEDUPE_WINDOW_MS = 60_000;
const SENTRY_DEDUPE_MAX_ENTRIES = 1000;
const sentryDedupe: Map<string, number> = new Map();

/**
 * True when a pino-serialized error represents an expected client fault that
 * should NOT be forwarded to Sentry: a `ToolUserError`, or anything carrying a
 * 4xx `httpStatus` (bad input, not-found, permission denied, conflict). These
 * are already returned to the caller as a 4xx and are not operational alerts.
 * Exported for direct unit testing (the integration suite runs with
 * `isolate: false`, so module-level mocking of this path is unreliable).
 */
export function isExpectedClientFaultLog(
  errObj: { type?: string; httpStatus?: number } | undefined
): boolean {
  if (!errObj) return false;
  if (errObj.type === 'ToolUserError') return true;
  const status = errObj.httpStatus;
  return typeof status === 'number' && status >= 400 && status < 500;
}

function fingerprintAndCapture(parsed: Record<string, unknown>): void {
  const level = parsed.level;
  if (level !== 'error' && level !== 'fatal') return;

  // Caller already captured this to Sentry (see server.ts onError +
  // 500-response middleware). Skip to avoid duplicate events.
  if (parsed.sentryReported === true) return;

  const msg = typeof parsed.msg === 'string' ? parsed.msg : 'logger.error';
  // pino.stdSerializers.err normalises both `err` and `error` (see serializers
  // config below) to objects with `type` / `message` / `stack` (plus any own
  // enumerable fields such as ToolUserError's `httpStatus`).
  const errObj =
    (parsed.err as
      | { type?: string; message?: string; stack?: string; httpStatus?: number }
      | undefined) ??
    (parsed.error as
      | { type?: string; message?: string; stack?: string; httpStatus?: number }
      | undefined);

  // Expected client-fault outcomes (ToolUserError and anything carrying a 4xx
  // httpStatus — bad input, not-found, permission denied, conflict) are already
  // returned to the caller as a 4xx response; they are NOT operational alerts.
  // `trackMCPToolCall` / `captureServerError` already skip them at the
  // captureException layer, but a handler that *logs* the error (e.g.
  // `routeAction`'s catch) still reaches this pino bridge. Skip here too so the
  // three capture paths stay consistent and the alert feed stays clean.
  if (isExpectedClientFaultLog(errObj)) return;

  // Include err.message in the fingerprint — pre-fix, "(msg, err.type,
  // top stack frame)" grouped distinct errors raised from the same
  // catch site (same Error type, same wrapping log line). One legit
  // incident could be masked by a noisy unrelated one within the 60s
  // window. err.message disambiguates them.
  const errType = errObj?.type ?? '';
  const errMessage = errObj?.message ?? '';
  const stackTop = (errObj?.stack ?? '').split('\n')[1]?.trim() ?? '';
  const fingerprint = `${msg}|${errType}|${errMessage}|${stackTop}`;

  const now = Date.now();
  const last = sentryDedupe.get(fingerprint);
  if (last !== undefined && now - last < SENTRY_DEDUPE_WINDOW_MS) return;
  sentryDedupe.set(fingerprint, now);

  // Bound the dedupe map so a long-running pod doesn't grow it without limit.
  if (sentryDedupe.size > SENTRY_DEDUPE_MAX_ENTRIES) {
    const oldest = sentryDedupe.keys().next().value;
    if (oldest !== undefined) sentryDedupe.delete(oldest);
  }

  try {
    if (errObj?.message) {
      // Reconstruct an Error so Sentry's grouping works on the stack.
      const reconstructed = new Error(errObj.message);
      if (errObj.stack) reconstructed.stack = errObj.stack;
      Sentry.captureException(reconstructed, {
        extra: parsed,
        tags: { source: 'pino', level: String(level) },
      });
    } else {
      Sentry.captureMessage(msg, {
        level: level === 'fatal' ? 'fatal' : 'error',
        extra: parsed,
        tags: { source: 'pino' },
      });
    }
  } catch {
    // Sentry not initialised (test envs) or transient SDK failure — never
    // crash the logger over telemetry.
  }
}

/**
 * pino destination that mirrors lines to stdout AND inspects each line for
 * Sentry forwarding. Sync write is intentional: pino's default stdout path
 * is sync too, and the JSON.parse + dedupe lookup is sub-microsecond.
 */
const sentryAwareStream: pino.DestinationStream = {
  write(line: string): void {
    process.stdout.write(line);
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      return;
    }
    if (parsed && typeof parsed === 'object') {
      fingerprintAndCapture(parsed as Record<string, unknown>);
    }
  },
};

const logger = pino(
  {
    level: getLogLevel(),
    browser: {
      asObject: false,
    },
    formatters: {
      level: (label) => {
        return { level: label };
      },
    },
    redact: {
      paths: [...HTTP_SECRET_HEADER_PATHS],
      censor: '[redacted]',
    },
    serializers: {
      err: errSerializer,
      error: errSerializer,
    },
  },
  sentryAwareStream
);

export default logger;
/**
 * Tests for the pino → Sentry forwarding guard in utils/logger.ts.
 *
 * Expected client-fault outcomes (ToolUserError / 4xx httpStatus) must NOT be
 * forwarded to Sentry — they are returned to the caller as a 4xx and are not
 * operational alerts. Genuine operational errors must still be captured. This
 * is the path that previously turned routine 409/403 tool outcomes into Sentry
 * issues (LOBU-BACKEND-12, LOBU-BACKEND-Z, LOBU-BACKEND-11).
 *
 * Tested via the exported pure predicate rather than by mocking `@sentry/node`:
 * the integration suite runs with `isolate: false` (shared module registry),
 * so per-file module mocks of an already-loaded singleton are unreliable.
 */

import { describe, expect, it, vi } from 'vitest';
import logger, { isExpectedClientFaultLog } from '../logger';

describe('HTTP secret redaction', () => {
  it('redacts credentials from request and response headers', () => {
    const write = vi.spyOn(process.stdout, 'write').mockImplementation(() => true);
    let output = '';

    try {
      logger.info(
        {
          req: {
            headers: {
              authorization: 'Bearer request-secret',
              cookie: 'session=request-cookie',
              'proxy-authorization': 'Basic proxy-secret',
              'x-api-key': 'api-key-secret',
            },
          },
          res: {
            headers: {
              'set-cookie': 'session=response-cookie',
            },
          },
        },
        'request completed',
      );
      output = write.mock.calls.map(([line]) => String(line)).join('');
    } finally {
      write.mockRestore();
    }

    expect(output).toContain('request completed');
    expect(output).not.toContain('request-secret');
    expect(output).not.toContain('request-cookie');
    expect(output).not.toContain('proxy-secret');
    expect(output).not.toContain('api-key-secret');
    expect(output).not.toContain('response-cookie');
    expect(output).toContain('[redacted]');
  });
});

describe('isExpectedClientFaultLog', () => {
  it('skips a ToolUserError regardless of status', () => {
    expect(isExpectedClientFaultLog({ type: 'ToolUserError', httpStatus: 409 })).toBe(true);
    expect(isExpectedClientFaultLog({ type: 'ToolUserError' })).toBe(true);
  });

  it('skips any 4xx httpStatus (e.g. a 403 thrown as a plain Error)', () => {
    expect(isExpectedClientFaultLog({ type: 'Error', httpStatus: 403 })).toBe(true);
    expect(isExpectedClientFaultLog({ httpStatus: 400 })).toBe(true);
    expect(isExpectedClientFaultLog({ httpStatus: 499 })).toBe(true);
  });

  it('forwards genuine operational errors (no 4xx status, not a ToolUserError)', () => {
    expect(isExpectedClientFaultLog({ type: 'Error', message: 'db boom' })).toBe(false);
    expect(isExpectedClientFaultLog({ type: 'Error', httpStatus: 500 })).toBe(false);
    expect(isExpectedClientFaultLog({ httpStatus: 503 })).toBe(false);
    expect(isExpectedClientFaultLog(undefined)).toBe(false);
  });
});
