import { afterEach, describe, expect, mock, spyOn, test } from "bun:test";
import { createLogger } from "../logger.js";

describe("console logger", () => {
  afterEach(() => {
    mock.restore();
  });

  test("preserves structured metadata in pino-style calls", () => {
    const lines: string[] = [];
    spyOn(console, "error").mockImplementation((line) => {
      lines.push(String(line));
    });

    createLogger("acl-sync").error(
      {
        organization_id: "org-123",
        connection_id: "connection-456",
        error: "GitHub API unavailable",
      },
      "GitHub ACL sync failed"
    );

    expect(lines).toHaveLength(1);
    expect(lines[0]).toContain("GitHub ACL sync failed");
    expect(lines[0]).toContain('"organization_id":"org-123"');
    expect(lines[0]).toContain('"connection_id":"connection-456"');
    expect(lines[0]).toContain('"error":"GitHub API unavailable"');
  });
});

