  {
    level: getLogLevel(),
    browser: {
      asObject: false,
    },
    formatters: {
      level: (label) => {
        return { level: label };
      },
    },
    redact: {
      paths: [...HTTP_HEADER_PATHS],
      censor: censorHttpHeader,
    },
    serializers: {
      err: errSerializer,
      error: errSerializer,
    },
  },
  sentryAwareStream
);

